// grabs all config from DOM data attributes on the docViewerContainer
// template usage: just add data-* attributes to #docViewerContainer
// example: data-courtroom-id="{{ courtroom.id }}" data-judges='{{ judges_json | tojson }}'

export class DocViewerConfig {
  constructor(containerId = 'docViewerContainer') {
    this.container = document.getElementById(containerId);
    
    if (!this.container) {
      console.error(`Container with id "${containerId}" not found`);
      this.config = this.getDefaultConfig();
      return;
    }

    this.config = this.extractConfig();
  }

  // pull all config from data attributes
  extractConfig() {
    const dataset = this.container.dataset;

    return {
      courtroomId: dataset.courtroomId || null,
      caseId: dataset.caseId || null,
      caseGuid: dataset.caseGuid || null,

      currentUserId: dataset.currentUserId || null,
      currentUserName: dataset.currentUserName || null,
      currentUserRole: dataset.currentUserRole || null, // 'advocate' or 'judge'

      judges: this.parseJsonSafe(dataset.judges, []),
      url: dataset.url || null,
      
      enableSocketFeature: dataset.enableSocketFeature === 'true',
      showAccordion: dataset.showAccordion === 'true',
      showBackButton: dataset.showBackButton === 'true',
      showEditItemButton: dataset.showEditItemButton === 'true',
      showJudgementActions: dataset.showJudgementActions === 'true',

      design: dataset.design || 'default',
      heading: dataset.heading || 'Document Viewer',
      subHeading: dataset.subHeading || '',

      backUrl: dataset.backUrl || '#',
      editLink: dataset.editLink || null,
      passJudgementUrl: dataset.passJudgementUrl || null,
      finalJudgementUrl: dataset.finalJudgementUrl || null,

      annotationBaseUrl: dataset.annotationBaseUrl || '',
      annoGet: dataset.annoGet || null,
      annoPost: dataset.annoPost || null,
      imgAnnoGet: dataset.imgAnnoGet || null,
      imgAnnoPost: dataset.imgAnnoPost || null,

      documents: this.parseJsonSafe(dataset.documents, {}),
      currentFileuuid: dataset.currentFileuuid || null,
      judgementFinal: dataset.judgementFinal === 'true',
      
      polling: {
        enabled: dataset.pollingEnabled !== 'false',
        interval: parseInt(dataset.pollingInterval) || 5000,
        onFetchCommentUpdates: null,
        onFetchCommentUpdatesOverride: false,
        onFetchMediaUpdates: null,
        onFetchMediaUpdatesOverride: false,
        onFetchDocumentUpdates: null,
        onFetchDocumentUpdatesOverride: false,
        onFetchNoteUpdates: null,
        onFetchNoteUpdatesOverride: false
      }
    };
  }

  // fallback config if container not found
  getDefaultConfig() {
    return {
      courtroomId: null,
      caseId: null,
      caseGuid: null,
      currentUserId: null,
      currentUserName: null,
      currentUserRole: null,
      judges: [],
      url: null,
      enableSocketFeature: false,
      showAccordion: false,
      showBackButton: false,
      showEditItemButton: false,
      showJudgementActions: false,
      design: 'default',
      heading: 'Document Viewer',
      subHeading: '',
      backUrl: '#',
      editLink: null,
      passJudgementUrl: null,
      finalJudgementUrl: null,
      annotationBaseUrl: '',
      annoGet: null,
      annoPost: null,
      imgAnnoGet: null,
      imgAnnoPost: null,
      documents: {},
      currentFileuuid: null,
      judgementFinal: false,
      
      polling: {
        enabled: true,
        interval: 5000,
        onFetchCommentUpdates: null,
        onFetchCommentUpdatesOverride: false,
        onFetchMediaUpdates: null,
        onFetchMediaUpdatesOverride: false,
        onFetchDocumentUpdates: null,
        onFetchDocumentUpdatesOverride: false,
        onFetchNoteUpdates: null,
        onFetchNoteUpdatesOverride: false
      }
    };
  }

  // parse JSON without crashing if it's malformed
  parseJsonSafe(jsonString, defaultValue = null) {
    if (!jsonString) return defaultValue;
    
    try {
      return JSON.parse(jsonString);
    } catch (error) {
      console.error('Failed to parse JSON:', error, jsonString);
      return defaultValue;
    }
  }

  getConfig() {
    return this.config;
  }

  get(key) {
    return this.config[key];
  }

  // update config at runtime and sync back to DOM
  set(key, value) {
    this.config[key] = value;
    
    if (this.container && key in this.container.dataset) {
      if (typeof value === 'object') {
        this.container.dataset[key] = JSON.stringify(value);
      } else {
        this.container.dataset[key] = value;
      }
    }
  }

  getWebSocketConfig() {
    return {
      enableSocketFeature: this.config.enableSocketFeature,
      courtroomId: this.config.courtroomId,
      caseId: this.config.caseId,
      userId: this.config.currentUserId,
      userName: this.config.currentUserName,
      userRole: this.config.currentUserRole
    };
  }

  isAdvocate() {
    return this.config.currentUserRole === 'advocate';
  }

  isJudge() {
    return this.config.currentUserRole === 'judge';
  }

  isSocketEnabled() {
    return this.config.enableSocketFeature === true;
  }

  // quick check if we have the basics before doing full validation
  hasMinimumWebSocketData() {
    const dataset = this.container?.dataset;
    if (!dataset) return false;
    
    return !!(
      dataset.courtroomId && 
      dataset.caseId && 
      dataset.currentUserId &&
      dataset.currentUserRole
    );
  }

  // check if we have everything needed for websockets, returns { valid, errors }
  validateForWebSocket() {
    const errors = [];
    
    if (!this.config.courtroomId) {
      errors.push('courtroomId is required');
    }
    if (!this.config.caseId) {
      errors.push('caseId is required');
    }
    if (!this.config.currentUserId) {
      errors.push('currentUserId is required');
    }
    
    if (this.config.currentUserRole) {
      const validRoles = ['advocate', 'judge', 'admin'];
      if (!validRoles.includes(this.config.currentUserRole)) {
        errors.push(`currentUserRole must be one of: ${validRoles.join(', ')}`);
      }
    } else {
      errors.push('currentUserRole is required (advocate, judge, or admin)');
    }
    
    return {
      valid: errors.length === 0,
      errors: errors
    };
  }

  // dump config to console for debugging
  printConfig() {
    console.group('%c DocViewer Configuration', 'font-weight: bold; font-size: 14px; color: #2563eb');
    
    console.group('User Context');
    console.log('User ID:', this.config.currentUserId);
    console.log('User Name:', this.config.currentUserName);
    console.log('User Role:', this.config.currentUserRole);
    console.groupEnd();
    
    console.group('Courtroom Context');
    console.log('Courtroom ID:', this.config.courtroomId);
    console.log('Case ID:', this.config.caseId);
    console.log('Case GUID:', this.config.caseGuid);
    console.groupEnd();
    
    console.group('Judges');
    console.log('Count:', this.config.judges.length);
    console.table(this.config.judges);
    console.groupEnd();
    
    console.group('Feature Flags');
    console.log('Socket Enabled:', this.config.enableSocketFeature);
    console.log('Show Accordion:', this.config.showAccordion);
    console.log('Show Back Button:', this.config.showBackButton);
    console.log('Show Edit Button:', this.config.showEditItemButton);
    console.log('Show Judgement Actions:', this.config.showJudgementActions);
    console.groupEnd();
    
    console.group('Documents');
    console.log('Current File UUID:', this.config.currentFileuuid);
    console.log('Documents:', this.config.documents);
    console.groupEnd();
    
    console.group('URLs');
    console.log('Document URL:', this.config.url);
    console.log('Back URL:', this.config.backUrl);
    console.log('Edit Link:', this.config.editLink);
    console.log('Annotation Base URL:', this.config.annotationBaseUrl);
    console.groupEnd();
    
    console.group('Full Config Object');
    console.log(this.config);
    console.groupEnd();
    
    console.groupEnd();
    
    return this.config;
  }
}

export default DocViewerConfig;
