// websocket client for real-time document sharing between advocates and judges
// handles referrals, page sync, presence tracking, and session management

export class CourtroomWebSocket {
  constructor(config) {
    this.config = {
      enabled: config.enableSocketFeature || false,
      courtroomId: config.courtroomId || null,
      caseId: config.caseId || null,
      userId: config.userId || null,
      userName: config.userName || null,
      userRole: config.userRole || null, // 'advocate' or 'judge'
      onReady: config.onReady || (() => {}),
      onError: config.onError || ((error) => console.error('WebSocket error:', error)),
      ...config
    };

    this.state = {
      isConnected: false,
      isReconnecting: false,
      activeSessionId: null,
      role: this.config.userRole,
      sharingWith: null,
      viewingWith: null,
      allJudges: [],
      presentJudges: new Set(),
      pendingRequests: []
    };

    // callbacks that can be set via onConnect(), onDisconnect(), etc.
    this.callbacks = {
      onConnect: () => {},
      onDisconnect: () => {},
      onReconnect: () => {},
      onError: () => {},
      onJudgeAccepted: () => {},
      onJudgeRejected: () => {},
      onJudgeDisconnected: () => {},
      onReferralTimeout: () => {},
      onReferralRequest: () => {},
      onPageUpdate: () => {},
      onDocumentChanged: () => {},
      onSessionEnded: () => {},
      onSessionActive: () => {},
      onSessionResumed: () => {},
      onAdvocateDisconnected: () => {},
      onAdvocateReconnected: () => {},
      onJudgeStateChanged: () => {},
      onUserJoined: () => {},
      onUserLeft: () => {},
      onCaseLeft: () => {},
      onJudgeAddedToCourtroom: () => {},
      onJudgeRemovedFromCourtroom: () => {},
      onNotification: () => {}
    };

    this.socket = null;

    this.pageUpdateDebounceTimer = null;

    if (!this.config.enabled) {
      console.log('WebSocket features disabled via configuration');
      return;
    }

    if (typeof io === 'undefined') {
      console.warn('Socket.IO not available. Document sharing features will be disabled.');
      this.config.onError(new Error('Socket.IO library not loaded'));
      return;
    }

    // make sure we have all the required config
    if (!this.config.courtroomId || !this.config.userId || !this.config.userRole) {
      console.error('WebSocket initialization failed: missing required config', {
        courtroomId: this.config.courtroomId,
        userId: this.config.userId,
        userRole: this.config.userRole
      });
      return;
    }

    this.initialize();
  }

  initialize() {
    try {
      this.socket = io({
        transports: ['websocket', 'polling'],
        reconnection: true,
        reconnectionDelay: 1000,
        reconnectionAttempts: 5
      });

      this.setupConnectionHandlers();
      this.setupDocumentSharingHandlers();
      this.setupPresenceHandlers();
      this.setupRosterHandlers();
      this.setupCleanup();

    } catch (error) {
      console.error('Failed to initialize WebSocket:', error);
      this.config.onError(error);
    }
  }

  /**
   * setup connection event handlers
   */
  setupConnectionHandlers() {
    // connection established
    this.socket.on('connect', () => {
      console.log('WebSocket connected');
      this.state.isConnected = true;
      
      // call external callback
      if (this.callbacks.onConnect) {
        this.callbacks.onConnect();
      }
    });

    // authentication confirmed
    this.socket.on('connected', (data) => {
      console.log('Authenticated:', data);
      
      // join case room only if this is NOT a reconnection
      // reconnect event will handle rejoining for reconnections
      if (!this.state.isReconnecting) {
        this.joinCase();
      }
    });

    // case room joined - backend sends 'joined_case' event
    this.socket.on('joined_case', (data) => {
      console.log('JOINED_CASE EVENT RECEIVED:', data);
      
      // initialize present judges from backend data (if provided)
      if (data.present_users && Array.isArray(data.present_users)) {
        console.log('Received present_users list, length:', data.present_users.length);
        data.present_users.forEach(user => {
          console.log('Present user:', user.user_name, 'Role:', user.role, 'ID:', user.user_id);
          if (user.role === 'judge') {
            // ensure id is stored as string for consistent comparison
            const judgeId = String(user.user_id);
            this.state.presentJudges.add(judgeId);
            console.log('Added judge to presentJudges:', judgeId, user.user_name);
          }
        });
        console.log('Total judges online after initialization:', this.state.presentJudges.size);
        console.log('Present judge IDs:', Array.from(this.state.presentJudges));
      } else {
        console.warn('Backend did not send present_users - presence tracking will only work for future joins');
      }
    });

    // disconnection
    this.socket.on('disconnect', (reason) => {
      console.log('WebSocket disconnected:', reason);
      this.state.isConnected = false;
      this.state.isReconnecting = true;
      
      // if advocate disconnects during active session, backend starts grace period
      if (this.state.activeSessionId && this.state.role === 'advocate') {
        console.log('Disconnected during active session - 30s grace period started on server');
      }
      
      // call external callback
      if (this.callbacks.onDisconnect) {
        this.callbacks.onDisconnect(reason);
      }
    });

    // reconnection
    this.socket.on('reconnect', (attemptNumber) => {
      console.log('WebSocket reconnected after', attemptNumber, 'attempts');
      this.state.isConnected = true;
      
      // rejoin case room
      this.joinCase();
      
      // reset reconnecting flag after successful reconnect
      this.state.isReconnecting = false;
      
      // call external callback
      if (this.callbacks.onReconnect) {
        this.callbacks.onReconnect();
      }
    });

    // generic error handler
    this.socket.on('error', (data) => {
      console.error('WebSocket error:', data);
      this.showNotification('error', data.message || 'An error occurred');
      
      // call external callback
      if (this.callbacks.onError) {
        this.callbacks.onError(data);
      }
    });
  }

  /**
   * join case room on the server
   */
  joinCase() {
    if (!this.config.courtroomId || !this.config.caseId) {
      console.error('Cannot join case: missing courtroom or case ID');
      return;
    }

    this.socket.emit('join_case', {
      courtroom_id: this.config.courtroomId,
      case_id: this.config.caseId,
      user_id: this.config.userId,
      role: this.state.role
    });

    console.log('Joined case room:', {
      courtroom: this.config.courtroomId,
      case: this.config.caseId,
      role: this.state.role
    });
  }

  /**
   * leave case room
   */
  leaveCase() {
    if (!this.socket || !this.config.courtroomId || !this.config.caseId) {
      return;
    }

    this.socket.emit('leave_case', {
      courtroom_id: this.config.courtroomId,
      case_id: this.config.caseId,
      role: this.state.role
    });

    console.log('Left case room');
  }

  /**
   * setup document sharing event handlers
   */
  setupDocumentSharingHandlers() {
    // for judges: receive referral request
    this.socket.on('referral_request', (data) => {
      console.log('Received referral request:', data);
      
      // filter: if there's a target_judge_id in the request, only process if it matches this user
      // (for individual judge requests during active session)
      if (data.target_judge_id && data.target_judge_id !== this.config.userId) {
        console.log('Request not for this judge, ignoring:', data.target_judge_id, 'vs', this.config.userId);
        return;
      }
      
      // add to pending requests queue
      this.state.pendingRequests.push(data);
      
      // Store in localStorage so all tabs can access document info when accepting
      try {
        const storageKey = `referral_${this.config.courtroomId}_${this.config.userId}`;
        localStorage.setItem(storageKey, JSON.stringify(data));
      } catch (e) {
        console.warn('Could not store referral in localStorage:', e);
      }
      
      // send confirmation back to backend that request was received by this judge's client
      this.socket.emit('confirm_request_received', {
        courtroom_id: data.courtroom_id,
        judge_id: this.config.userId
      });
      
      // call external callback
      if (this.callbacks.onReferralRequest) {
        this.callbacks.onReferralRequest(data);
      }
    });

    // backend sends: judge_state_changed (for advocates to track judge status changes)
    this.socket.on('judge_state_changed', (data) => {
      console.log('Judge state changed:', data);
      
      // set activeSessionId when FIRST judge accepts (session becomes active)
      if (data.state === 'accepted' && !this.state.activeSessionId) {
        this.state.activeSessionId = true; // mark session as active
        console.log('Session is now active - first judge accepted');
      }
      
      // call generic callback for ALL state changes (pending, accepted, rejected, reconnections)
      if (this.callbacks.onJudgeStateChanged) {
        this.callbacks.onJudgeStateChanged(data);
      }
      
      // ONLY call specific callbacks for ADVOCATES (not judges)
      // Judges get their own unicast events (referral_accepted, referral_rejected)
      // This prevents ALL judges from opening share viewer when ONE judge accepts
      if (this.state.role === 'advocate') {
        if (data.state === 'accepted' && this.callbacks.onJudgeAccepted) {
          this.callbacks.onJudgeAccepted(data);
        } else if (data.state === 'rejected' && this.callbacks.onJudgeRejected) {
          this.callbacks.onJudgeRejected(data);
        }
      }
    });

    // for advocates: request timeout (backend needs to implement this - see BACKEND_WEBSOCKET_ADDITIONS.py)
    this.socket.on('referral_timeout', (data) => {
      console.log('Referral timeout:', data);
      
      this.showNotification('warning', `${data.judge_name || 'Judge'} did not respond`);
      
      // call external callback
      if (this.callbacks.onReferralTimeout) {
        this.callbacks.onReferralTimeout(data);
      }
    });

    // backend sends: page_updated (for judges to receive page changes from advocate)
    this.socket.on('page_updated', (data) => {
      console.log('Page updated:', data);
      
      // call external callback
      if (this.callbacks.onPageUpdate) {
        this.callbacks.onPageUpdate(data);
      }
    });

    // backend sends: document_changed (for judges when advocate switches to a new PDF file)
    // backend handler added in BACKEND_WEBSOCKET_ADDITIONS.py - needs to be integrated
    this.socket.on('document_changed', (data) => {
      console.log('Document changed:', data);
      
      // call external callback
      if (this.callbacks.onDocumentChanged) {
        this.callbacks.onDocumentChanged(data);
      }
    });

    // for both: session ended
    this.socket.on('session_ended', (data) => {
      console.log('Session ended:', data);
      
      // reset state
      this.state.activeSessionId = null;
      this.state.sharingWith = null;
      this.state.viewingWith = null;
      
      // call external callback
      if (this.callbacks.onSessionEnded) {
        this.callbacks.onSessionEnded(data);
      }
    });

    // for judges: advocate disconnected (grace period started)
    this.socket.on('advocate_disconnected', (data) => {
      console.log('Advocate disconnected:', data);
      
      // call external callback
      if (this.callbacks.onAdvocateDisconnected) {
        this.callbacks.onAdvocateDisconnected(data);
      }
    });

    // for judges: advocate reconnected (backend currently uses session_resumed to advocate directly)
    // see BACKEND_WEBSOCKET_ADDITIONS.py for how to add judge notification
    this.socket.on('advocate_reconnected', (data) => {
      console.log('Advocate reconnected:', data);
      
      // call external callback
      if (this.callbacks.onAdvocateReconnected) {
        this.callbacks.onAdvocateReconnected(data);
      }
    });

    // backend sends: session_started (when first judge accepts)
    this.socket.on('session_started', (data) => {
      console.log('Session started:', data);
      this.state.activeSessionId = true; // mark session as active
    });

    // backend sends: request_created (confirmation that request was sent)
    this.socket.on('request_created', (data) => {
      console.log('Request created:', data);
      
      // NOTE: do NOT set activeSessionId here - only set it when a judge ACCEPTS
      // this allows sending requests to all judges without blocking
      
      // show success notification
      if (data.message) {
        this.showNotification('success', data.message);
      }
    });

    // for advocates: confirmation that judge received the request (from judge's client)
    this.socket.on('request_received_confirmation', (data) => {
      console.log('Judge confirmed receiving request:', data);
      
      // call external callback to update UI
      if (this.callbacks.onRequestReceivedConfirmation) {
        this.callbacks.onRequestReceivedConfirmation(data);
      }
    });

    // backend sends: referral_accepted (for judges when they accept)
    this.socket.on('referral_accepted', (data) => {
      console.log('Referral accepted by me:', data);
      this.state.activeSessionId = true;
      if (data.advocate_name) {
        this.state.viewingWith = data.advocate_name;
      }
      
      // call judge accepted callback
      if (this.callbacks.onJudgeAccepted) {
        this.callbacks.onJudgeAccepted(data);
      }
    });

    // backend sends: referral_rejected (for judges when they reject)
    this.socket.on('referral_rejected', (data) => {
      console.log('Referral rejected event received:', data);
      
      // FILTER: Only process if this event is for THIS user (multi-tab sync for same judge)
      // Backend broadcasts to room so all tabs of rejecting judge get it
      // But we need to prevent other judges and advocates from processing it
      if (data.judge_id && data.judge_id !== this.config.userId) {
        console.log('Rejection not for this user, ignoring:', data.judge_id, 'vs', this.config.userId);
        return;
      }
      
      console.log('Referral rejected by me:', data);
      
      // clear any active session state
      this.state.activeSessionId = null;
      this.state.viewingWith = null;
      
      // call callback to close modal on all tabs
      if (this.callbacks.onJudgeRejected) {
        this.callbacks.onJudgeRejected(data);
      }
      
      // show notification
      if (data.message) {
        this.showNotification('info', data.message);
      }
    });

    // backend sends: disconnect_countdown (during grace period)
    this.socket.on('disconnect_countdown', (data) => {
      console.log('Disconnect countdown:', data.remaining_seconds, 'seconds remaining');
      
      // notify UI layer about countdown for potential banner updates
      if (this.callbacks.onAdvocateDisconnected) {
        // pass countdown info to UI layer
        this.callbacks.onAdvocateDisconnected({
          type: 'countdown',
          remaining_seconds: data.remaining_seconds
        });
      }
    });

    // backend sends: session_resumed (when advocate reconnects)
    this.socket.on('session_resumed', (data) => {
      console.log('Session resumed:', data);
      this.state.activeSessionId = data.session?.id || true;
      // restore advocate state - extract judge names from session
      if (data.session?.judges) {
        const acceptedJudges = Object.values(data.session.judges)
          .filter(j => j.state === 'accepted')
          .map(j => j.name);
        this.state.sharingWith = acceptedJudges.join(', ') || null;
      }
      
      // call external callback to restore advocate UI
      if (this.callbacks.onSessionResumed) {
        this.callbacks.onSessionResumed(data);
      }
    });

    // backend sends: session_active (for judges rejoining active session)
    this.socket.on('session_active', (data) => {
      console.log('Judge rejoining active session:', data);
      this.state.activeSessionId = data.session_id || true;
      this.state.viewingWith = data.advocate_name;
      
      // call external callback to restore shared viewer
      if (this.callbacks.onSessionActive) {
        this.callbacks.onSessionActive(data);
      }
    });

    // backend sends: left_case (confirmation of leaving case room)
    this.socket.on('left_case', (data) => {
      console.log('Left case confirmed:', data);
      
      // clean up all session state
      this.state.activeSessionId = null;
      this.state.sharingWith = null;
      this.state.viewingWith = null;
      this.state.pendingRequests = [];
      
      console.log('Cleaned up case state after leaving');
      
      // call external callback for ui cleanup
      if (this.callbacks.onCaseLeft) {
        this.callbacks.onCaseLeft(data);
      }
    });
  }

  /**
   * setup presence tracking handlers
   */
  setupPresenceHandlers() {
    // user joined case
    this.socket.on('user_joined_case', (data) => {
      console.log('User joined case:', data);
      
      if (data.role === 'judge') {
        // add to present judges set (ensure string for consistent comparison)
        const judgeId = String(data.user_id);
        this.state.presentJudges.add(judgeId);
        console.log('Added judge to presence:', judgeId, data.user_name);
      }
      
      console.log('Total judges online:', this.state.presentJudges.size);
      console.log('Present judge IDs:', Array.from(this.state.presentJudges));
      
      // call external callback
      if (this.callbacks.onUserJoined) {
        this.callbacks.onUserJoined(data);
      }
    });

    // user left case
    this.socket.on('user_left_case', (data) => {
      console.log('User left case:', data);
      
      if (data.role === 'judge') {
        // remove from present judges set (ensure string for consistent comparison)
        const judgeId = String(data.user_id);
        this.state.presentJudges.delete(judgeId);
        console.log('Removed judge from presence:', judgeId);
      }
      
      console.log('Total judges online:', this.state.presentJudges.size);
      console.log('Present judge IDs:', Array.from(this.state.presentJudges));
      
      // call external callback
      if (this.callbacks.onUserLeft) {
        this.callbacks.onUserLeft(data);
      }
    });
  }

  /**
   * setup courtroom roster change handlers
   */
  setupRosterHandlers() {
    // judge added to courtroom
    this.socket.on('judge_added_to_courtroom', (data) => {
      console.log('Judge added to courtroom:', data);
      
      if (data.courtroom_id === this.config.courtroomId) {
        // add to all judges list
        this.state.allJudges.push(data.judge);
        
        // call external callback
        if (this.callbacks.onJudgeAddedToCourtroom) {
          this.callbacks.onJudgeAddedToCourtroom(data);
        }
      }
    });

    // judge removed from courtroom
    this.socket.on('judge_removed_from_courtroom', (data) => {
      console.log('Judge removed from courtroom:', data);
      
      if (data.courtroom_id === this.config.courtroomId) {
        // remove from all judges list
        this.state.allJudges = this.state.allJudges.filter(j => j.id !== data.judge_id);
        
        // remove from presence tracking
        this.state.presentJudges.delete(data.judge_id);
        
        // call external callback
        if (this.callbacks.onJudgeRemovedFromCourtroom) {
          this.callbacks.onJudgeRemovedFromCourtroom(data);
        }
      }
    });
  }

  /**
   * setup cleanup handlers
   */
  setupCleanup() {
    // use pagehide instead of unload (modern, policy-compliant)
    // pagehide fires when page is being unloaded or enters bfcache
    window.addEventListener('pagehide', () => {
      this.leaveCase();
    });
    
    // also leave on visibility change (when page becomes hidden for extended period)
    // NOTE: this is commented out to avoid excessive disconnects during tab switches 
    // document.addEventListener('visibilitychange', () => {
    //   if (document.visibilityState === 'hidden') {
    //     this.leaveCase();
    //   }
    // });
  }

  // public api methods

  /**
   * broadcast referral request to multiple judges (advocate only)
   * sends ONE request with ALL judges - matching backend design
   */
  broadcastReferralRequest(judgeList, documentId, documentUrl, pageNumber) {
    if (this.state.role !== 'advocate') {
      console.error('Only advocates can broadcast referrals');
      return;
    }

    if (!this.state.isConnected) {
      console.error('WebSocket not connected');
      this.showNotification('error', 'Not connected. Please refresh the page.');
      return;
    }

    if (judgeList.length === 0) {
      console.error('No judges provided for referral');
      return;
    }

    console.log('Broadcasting referral to judges:', judgeList);

    // format judge list for backend: [{user_id, name}, ...]
    const judge_ids = judgeList.map(judge => ({
      user_id: judge.id,
      name: judge.name
    }));

    this.socket.emit('create_referral_request', {
      courtroom_id: this.config.courtroomId,
      case_id: this.config.caseId,
      document_id: documentId,
      document_url: documentUrl,
      pageNumber: pageNumber,
      judge_ids: judge_ids  // send ALL judges in one request
    });
  }

  /**
   * add a single judge to an existing active session (advocate only)
   * used for: resending to rejected judges, adding newly joined judges
   */
  addJudgeToActiveSession(judgeId, judgeName) {
    if (this.state.role !== 'advocate') {
      console.error('Only advocates can add judges to session');
      return;
    }

    if (!this.state.activeSessionId) {
      console.error('No active session to add judge to');
      this.showNotification('warning', 'No active session');
      return;
    }

    if (!this.state.isConnected) {
      console.error('WebSocket not connected');
      this.showNotification('error', 'Not connected. Please refresh the page.');
      return;
    }

    console.log('Adding judge to active session:', judgeName, judgeId);

    this.socket.emit('add_judge_to_active_session', {
      courtroom_id: this.config.courtroomId,
      judge_id: judgeId,
      judge_name: judgeName,
      target_judge_id: judgeId  // Include target for judge-side filtering
    });
  }

  /**
   * initiate document referral (advocate only)
   * @deprecated Use broadcastReferralRequest for multiple judges
   */
  initiateReferral(judgeUserId, documentId, documentUrl, pageNumber) {
    if (this.state.role !== 'advocate') {
      console.error('Only advocates can initiate referrals');
      return;
    }

    // removed activeSessionId check - let backend validate session state
    // this allows for both initial requests and adding judges to active sessions

    if (!this.state.isConnected) {
      console.error('WebSocket not connected');
      this.showNotification('error', 'Not connected. Please refresh the page.');
      return;
    }

    console.log('Initiating referral:', { judgeUserId, documentId, documentUrl, pageNumber });

    // get document URL (you may need to adjust this based on your document structure)
    // const documentUrl = documentId; // backend expects document_url

    this.socket.emit('create_referral_request', {
      courtroom_id: this.config.courtroomId,
      case_id: this.config.caseId,
      document_id: documentId,
      document_url: documentUrl,
      judge_ids: [{ user_id: judgeUserId, name: 'Judge' }] // backend expects array of judge objects
    });
  }

  /**
   * judge responds to referral request (judge only)
   */
  respondToReferral(sessionId, action, reason = null) {
    if (this.state.role !== 'judge') {
      console.error('Only judges can respond to referrals');
      return;
    }

    if (!['accept', 'reject'].includes(action)) {
      console.error('Invalid action. Must be "accept" or "reject"');
      return;
    }

    console.log('Responding to referral:', { action, reason });

    // backend expects separate events for accept and reject
    if (action === 'accept') {
      this.socket.emit('accept_referral', {
        courtroom_id: this.config.courtroomId
      });
    } else if (action === 'reject') {
      this.socket.emit('reject_referral', {
        courtroom_id: this.config.courtroomId
      });
    }

    // remove from pending requests
    this.state.pendingRequests = this.state.pendingRequests.filter(
      req => req.session_id !== sessionId
    );

    if (action === 'accept') {
      this.state.activeSessionId = sessionId;
      this.state.viewingWith = this.state.pendingRequests.find(
        req => req.session_id === sessionId
      )?.advocate_name;
    }
  }

  /**
   * update current page (advocate only - during active session)
   */
  updatePage(pageNumber) {
    if (this.state.role !== 'advocate') {
      return; // silently ignore for judges
    }

    if (!this.state.activeSessionId) {
      return; // no active session
    }

    console.log('Updating page:', pageNumber);

    if(this.pageUpdateDebounceTimer) {
      console.log('Clearing debounce :', this.pageUpdateDebounceTimer);
      clearTimeout(this.pageUpdateDebounceTimer);
      this.pageUpdateDebounceTimer == null;
    }

    this.pageUpdateDebounceTimer = setTimeout(() => {
      console.log('emitting page:', pageNumber);
      this.socket.emit('update_page', {
        courtroom_id: this.config.courtroomId,
        page: pageNumber
      });
      this.pageUpdateDebounceTimer == null;
    }, 300); 
  }

  /**
   * update current document (advocate only - when switching to a new PDF file during active session)
   */
  updateDocument(documentUrl, pageNumber = 1) {
    if (this.state.role !== 'advocate') {
      return; // silently ignore for judges
    }

    if (!this.state.activeSessionId) {
      return; // no active session
    }

    console.log('Updating document:', documentUrl, 'page:', pageNumber);

    this.socket.emit('update_document', {
      courtroom_id: this.config.courtroomId,
      document_url: documentUrl,
      page: pageNumber
    });
  }

  /**
   * end referral session (advocate only)
   */
  endReferral() {
    if (this.state.role !== 'advocate') {
      console.error('Only advocates can end referrals');
      return;
    }

    if (!this.state.activeSessionId) {
      console.error('No active session to end');
      return;
    }

    console.log('Ending referral session:', this.state.activeSessionId);

    this.socket.emit('end_referral', {
      courtroom_id: this.config.courtroomId
    });

    // state will be reset when session_ended event is received
  }

  /**
   * set complete judge list (called on page load)
   */
  setJudgeList(judges) {
    this.state.allJudges = judges || [];
    console.log('Judge list set:', this.state.allJudges);
  }

  /**
   * get list of available (online) judges
   */
  getAvailableJudges() {
    console.log('=== getAvailableJudges DEBUG ===');
    console.log('allJudges:', this.state.allJudges);
    console.log('presentJudges Set:', Array.from(this.state.presentJudges));
    
    const available = this.state.allJudges.filter(judge => {
      const judgeId = String(judge.id); // Ensure string comparison
      const isPresent = this.state.presentJudges.has(judgeId);
      console.log(`Judge ${judge.name} (ID: ${judgeId}): ${isPresent ? 'ONLINE' : 'OFFLINE'}`);
      return isPresent;
    });
    
    console.log('Available judges count:', available.length);
    console.log('=== END DEBUG ===');
    return available;
  }

  /**
   * get list of offline judges
   */
  getOfflineJudges() {
    return this.state.allJudges.filter(judge => 
      !this.state.presentJudges.has(judge.id)
    );
  }

  /**
   * check if currently in active sharing session
   */
  hasActiveSession() {
    return this.state.activeSessionId !== null;
  }

  /**
   * check if websocket is connected
   */
  isConnected() {
    return this.state.isConnected;
  }

  /**
   * get active session details (for UI)
   */
  getActiveSession() {
    if (!this.state.activeSessionId) {
      return null;
    }
    
    return {
      sessionId: this.state.activeSessionId,
      sharingWith: this.state.sharingWith,
      viewingWith: this.state.viewingWith,
      referrals: [] // UI layer tracks referrals, not websocket layer
    };
  }

  /**
   * get current session info
   */
  getSessionInfo() {
    return {
      sessionId: this.state.activeSessionId,
      sharingWith: this.state.sharingWith,
      viewingWith: this.state.viewingWith,
      role: this.state.role
    };
  }

  // ui helper methods (to be customized)
  /**
   * show referral request modal (judge)
   */
  showReferralRequestModal(data) {
    // this will be called by the UI layer
    if (this.config.onReferralRequest) {
      this.config.onReferralRequest(data);
    }
  }

  /**
   * show notification
   */
  showNotification(type, message, duration = 5000) {
    // call external callback if registered
    if (this.callbacks.onNotification) {
      this.callbacks.onNotification({type, message, duration});
    } else {
      // fallback to console
      console.log(`[${type.toUpperCase()}] ${message}`);
    }
  }

  /**
   * cleanup and disconnect
   */
  destroy() {
    if (this.socket) {
      this.leaveCase();
      this.socket.disconnect();
    }
  }

  // callback registration methods
  /**
   * register connection callback
   */
  onConnect(callback) {
    this.callbacks.onConnect = callback;
  }

  /**
   * register disconnection callback
   */
  onDisconnect(callback) {
    this.callbacks.onDisconnect = callback;
  }

  /**
   * register reconnection callback
   */
  onReconnect(callback) {
    this.callbacks.onReconnect = callback;
  }

  /**
   * register error callback
   */
  onError(callback) {
    this.callbacks.onError = callback;
  }

  /**
   * register judge accepted callback (advocate)
   */
  onJudgeAccepted(callback) {
    this.callbacks.onJudgeAccepted = callback;
  }

  /**
   * register judge rejected callback (advocate)
   */
  onJudgeRejected(callback) {
    this.callbacks.onJudgeRejected = callback;
  }
  /**
   * register generic judge state changed callback (for all state changes)
   */
  onRequestReceivedConfirmation(callback) {
    this.callbacks.onRequestReceivedConfirmation = callback;
  }

  onJudgeStateChanged(callback) {
    this.callbacks.onJudgeStateChanged = callback;
  }
  /**
   * register judge disconnected callback (advocate)
   */
  onJudgeDisconnected(callback) {
    this.callbacks.onJudgeDisconnected = callback;
  }

  /**
   * register referral timeout callback (advocate)
   */
  onReferralTimeout(callback) {
    this.callbacks.onReferralTimeout = callback;
  }

  /**
   * register referral request callback (judge)
   */
  onReferralRequest(callback) {
    this.callbacks.onReferralRequest = callback;
  }

  /**
   * register page update callback (judge)
   */
  onPageUpdate(callback) {
    this.callbacks.onPageUpdate = callback;
  }

  /**
   * register document changed callback (judge)
   */
  onDocumentChanged(callback) {
    this.callbacks.onDocumentChanged = callback;
  }

  /**
   * register session ended callback (judge)
   */
  onSessionEnded(callback) {
    this.callbacks.onSessionEnded = callback;
  }

  /**
   * register advocate disconnected callback (judge)
   */
  onAdvocateDisconnected(callback) {
    this.callbacks.onAdvocateDisconnected = callback;
  }

  /**
   * register advocate reconnected callback (judge)
   */
  onAdvocateReconnected(callback) {
    this.callbacks.onAdvocateReconnected = callback;
  }

  /**
   * register session active callback (judge reconnecting to active session)
   */
  onSessionActive(callback) {
    this.callbacks.onSessionActive = callback;
  }

  /**
   * register session resumed callback (advocate reconnecting to active session)
   */
  onSessionResumed(callback) {
    this.callbacks.onSessionResumed = callback;
  }

  /**
   * register user joined callback
   */
  onUserJoined(callback) {
    this.callbacks.onUserJoined = callback;
  }

  /**
   * register user left callback
   */
  onUserLeft(callback) {
    this.callbacks.onUserLeft = callback;
  }

  /**
   * register case left callback (when current user leaves case)
   */
  onCaseLeft(callback) {
    this.callbacks.onCaseLeft = callback;
  }

  /**
   * register judge added to courtroom callback
   */
  onJudgeAddedToCourtroom(callback) {
    this.callbacks.onJudgeAddedToCourtroom = callback;
  }

  /**
   * register judge removed from courtroom callback
   */
  onJudgeRemovedFromCourtroom(callback) {
    this.callbacks.onJudgeRemovedFromCourtroom = callback;
  }

  /**
   * register notification callback
   */
  onNotification(callback) {
    this.callbacks.onNotification = callback;
  }
}

// export for use in other modules
export default CourtroomWebSocket;
