// wires up WebSocket client and UI components into the DocViewer
// handles initialization, events, and page sync

import { CourtroomWebSocket } from './courtroom-websocket.mjs';
import { DocViewerConfig } from './docviewer-config.mjs';
import { DocumentSharingUI } from './document-sharing-ui.mjs';

export class DocumentSharingIntegration {
  constructor() {
    this.config = null;
    this.wsClient = null;
    this.ui = null;
    this.initialized = false;
    this.shareViewerInstance = null;
    this.dependenciesChecked = false;
    this.currentLoadedPage = 0;
    this.shareViewerInitialized = false;
    this.isSessionResumed = false;
  }

  // make sure Socket.IO, PDF.js, and elements exist before initializing
  checkDependencies() {
    const missing = [];

    if (typeof io === 'undefined') {
      missing.push('Socket.IO library (io)');
    }

    // Check for PDF.js viewer application
    if (typeof window.PDFViewerApplication === 'undefined') {
      missing.push('PDFViewerApplication');
    }

    const requiredElements = [
      { id: 'docViewerContainer', name: 'docViewerContainer element' },
      { id: 'referBtn', name: 'referBtn element (refer button)' },
      { id: 'judgeStatusList', name: 'judgeStatusList element (judge list)' }
    ];

    requiredElements.forEach(({ id, name }) => {
      if (!document.getElementById(id)) {
        missing.push(name);
      }
    });

    this.dependenciesChecked = true;

    return {
      available: missing.length === 0,
      missing
    };
  }

  // starting up document sharing after DocViewer is loaded
  async initialize(options = {}) {
    try {
      console.log('Initializing document sharing feature...');

      // Check dependencies first
      const dependencyCheck = this.checkDependencies();
      
      if (!dependencyCheck.available) {
        console.warn('Document sharing dependencies not met. Missing:', dependencyCheck.missing);
        console.warn('Feature will be disabled. This is expected if:');
        console.warn('  - Socket.IO script is not loaded');
        console.warn('  - Refer button template is not rendered (non-ecourt design)');
        console.warn('  - DocViewer is not fully initialized');
        return false;
      }

      console.log('All dependencies available');

      // Load configuration from DOM
      this.config = new DocViewerConfig();
      const wsConfig = this.config.getWebSocketConfig();

      // Check if feature is enabled (can be overridden by options)
      const featureEnabled = options.enableSocketFeature !== undefined 
        ? options.enableSocketFeature 
        : (wsConfig?.enableSocketFeature || false);

      if (!featureEnabled) {
        console.log('Document sharing feature is disabled (enableSocketFeature = false)');
        return false;
      }

      console.log('Feature enabled via configuration');

      // Validate configuration
      const validation = this.config.validateForWebSocket();
      if (!validation.valid) {
        console.warn('WebSocket configuration validation failed:');
        validation.errors.forEach(err => console.warn('  - ' + err));
        console.warn('');
        console.warn('Required data attributes on #docViewerContainer:');
        console.warn('  data-courtroom-id="{{ courtroom.id }}"');
        console.warn('  data-case-id="{{ case.id }}"');
        console.warn('  data-current-user-id="{{ current_user.id }}"');
        console.warn('  data-current-user-role="{{ current_user.role }}"  (advocate/judge/admin)');
        console.warn('');
        console.warn('Example:');
        console.warn('<div id="docViewerContainer"');
        console.warn('     data-courtroom-id="123"');
        console.warn('     data-case-id="456"');
        console.warn('     data-current-user-id="789"');
        console.warn('     data-current-user-name="John Doe"');
        console.warn('     data-current-user-role="advocate"');
        console.warn('     data-enable-socket-feature="true">');
        console.warn('</div>');
        return false;
      }

      console.log('Configuration validated');

      // Initialize WebSocket client (auto-connects in constructor)
      this.wsClient = new CourtroomWebSocket(wsConfig);

      // Set judge list from config
      const fullConfig = this.config.getConfig();
      if (fullConfig.judges && Array.isArray(fullConfig.judges)) {
        this.wsClient.setJudgeList(fullConfig.judges);
        console.log('Judge list initialized:', fullConfig.judges.length, 'judges');
      }

      // Set up WebSocket event callbacks
      this.setupWebSocketCallbacks();

      console.log('WebSocket initialized');

      // Initialize UI components
      this.ui = new DocumentSharingUI(this.wsClient, this.config);
      console.log('UI components initialized');

      // Set up page change synchronization
      this.setupPageSynchronization();

      // Set up share viewer
      this.setupShareViewer();

      this.initialized = true;
      console.log('Document sharing initialized successfully');
      
      return true;
    } catch (error) {
      console.error('Failed to initialize document sharing:', error);
      console.error('Stack trace:', error.stack);
      
      // Graceful degradation - don't break the application
      console.warn('Application will continue without document sharing feature');
      
      return false;
    }
  }

  /**
   * Set up WebSocket event callbacks
   */
  setupWebSocketCallbacks() {
    if (!this.wsClient) return;

    // Connection callbacks
    this.wsClient.onConnect(() => {
      console.log('Connected to courtroom WebSocket');
      
      // Join the case room after connection
      this.wsClient.joinCase();
      
      if (this.ui) {
        this.ui.showNotification('success', 'Connected to courtroom', 3000);
        // Update judge list after connection
        this.ui.updateAvailableJudgesList();
      }
    });

    this.wsClient.onDisconnect((reason) => {
      console.log('Disconnected from WebSocket:', reason);
      if (this.ui) {
        this.ui.showNotification('warning', 'Connection lost. Reconnecting...', 5000);
      }
    });

    this.wsClient.onReconnect(() => {
      console.log('Reconnected to WebSocket');
      if (this.ui) {
        this.ui.showNotification('success', 'Reconnected to courtroom', 3000);
      }
    });

    this.wsClient.onError((error) => {
      console.error('WebSocket error:', error);
      if (this.ui) {
        // check if error is about active session in courtroom
        if (error.message && error.message.includes('already has an active referral session')) {
          // reset button to default state when request fails due to active session
          this.ui.updateReferButtonState(1);
          this.ui.clearJudgeStates();
          this.ui.showNotification('warning', 'Another advocate is currently sharing in this courtroom', 5000);
        } else {
          this.ui.showNotification('error', error.message || 'Connection error occurred', 5000);
        }
      }
    });

    // Judge callbacks (judge role only)
    if (this.config.isJudge()) {
      this.wsClient.onReferralRequest((data) => {
        console.log('Received referral request:', data);
        if (this.ui) {
          this.ui.showReferralRequestModal(data);
        }
      });

      // When judge accepts - show share viewer with document
      this.wsClient.onJudgeAccepted((data) => {
        console.log('I accepted the referral:', data);
        
        // get advocate name from session data or check data.advocate_name
        const advocateName = data?.session?.advocate_name || data.advocate_name || 'Advocate';
        
        // Show viewing session banner
        if (this.ui) {
          // close the referral modal (in case open - so as to have it close in all)
          this.ui.hideReferralRequestModal();
          this.ui.showViewingSessionBanner(advocateName);
          this.ui.showNotification('success', 'Joined referral session', 3000);
        }
        
        this.hideSummaryButton();
        
        // Show share viewer with the document
        let documentUrl = null;
        let pageNumber = null;
        
        // Always retrieve from localStorage first (has the original referral request data)
        try {
          const storageKey = `referral_${this.wsClient.config.courtroomId}_${this.wsClient.config.userId}`;
          const storedData = localStorage.getItem(storageKey);
          if (storedData) {
            const referralData = JSON.parse(storedData);
            documentUrl = referralData.document_url;
            pageNumber = referralData.page_number;
            console.log('Retrieved document info from localStorage:', documentUrl, pageNumber);
          }
        } catch (e) {
          console.warn('Could not retrieve referral from localStorage:', e);
        }
        
        // Fallback to response data if localStorage doesn't have it
        if (!documentUrl) {
          documentUrl = data.session?.document_url;
        }
        if (!pageNumber) {
          pageNumber = data.session?.page_number || data.page_number || data.current_page || 1;
        }
        
        if (documentUrl) {
          console.log('Opening share viewer at page:', pageNumber);
          // using extracted advocate
          this.showShareViewer(documentUrl, pageNumber, advocateName);
          
          // show the stop share button for judge
          this.showJudgeStopButton();
        } else {
          console.error('No document URL available to show share viewer');
        }
      });

      // when rejects - close modal on any iuntance  if open
      this.wsClient.onJudgeRejected((data) => {
        console.log('self rejected:', data);
        
        // close the referral modal
        if (this.ui) {
          this.ui.hideReferralRequestModal();
        }
        
        // Clean up localStorage
        try {
          const storageKey = `referral_${this.wsClient.config.courtroomId}_${this.wsClient.config.userId}`;
          localStorage.removeItem(storageKey);
        } catch (e) {
          console.warn('Could not remove referral from localStorage:', e);
        }
      });

      this.wsClient.onPageUpdate((data) => {
        console.log('Page update from advocate:', data);
        this.syncToPage(data.page || data.page_number);
      });

      // Listen for document changes (when advocate clicks a new PDF file)
      this.wsClient.onDocumentChanged((data) => {
        console.log('Advocate changed document:', data);
        if (this.ui) {
          this.ui.showNotification('info', 'Document updated', 2000);
        }
        // Load the new document in share viewer
        if (data.document_url) {
          const pageNumber = data.page_number || 1;
          this.showShareViewer(data.document_url, pageNumber, data.advocate_name);
        }
      });

      this.wsClient.onSessionEnded((data) => {
        console.log('Sharing session ended:', data);
        if (this.ui) {
          this.ui.clearJudgeStates(); // clear tracked judge states
          this.ui.hideViewingSessionBanner();
          this.ui.hideReferralRequestModal(); // close any open request popups
          this.ui.showNotification('info', data.message || 'Session ended', 5000);
        }
        this.hideShareViewer();
        
        // hide judge stop button
        this.hideJudgeStopButton();
        
        this.showSummaryButton();
        
        // Clean up localStorage
        try {
          const storageKey = `referral_${this.wsClient.config.courtroomId}_${this.wsClient.config.userId}`;
          localStorage.removeItem(storageKey);
        } catch (e) {
          console.warn('Could not remove referral from localStorage:', e);
        }
      });

      this.wsClient.onAdvocateDisconnected((data) => {
        console.log('Advocate disconnected, grace period active');
        if (this.ui) {
          this.ui.showAdvocateDisconnectedBanner(data.grace_seconds || 30);
        }
      });

      this.wsClient.onAdvocateReconnected((data) => {
        console.log('Advocate reconnected:', data);
        if (this.ui) {
          this.ui.hideAdvocateDisconnectedBanner();
          // Use advocate name from event data
          const advocateName = data?.advocate_name || 'Advocate';
          this.ui.showNotification('success', `${advocateName} reconnected`, 3000);
        }
      });

      this.wsClient.onSessionActive((data) => {
         if (this.shareViewerInitialized) {
          console.log('Share viewer already initialized, ignoring duplicate session_active event.');
          return;
        }
        this.hideSummaryButton();
        
        this.shareViewerInitialized = true;

        console.log('Judge reconnected to active session:', data);
        if (this.ui) {
          this.ui.showNotification('info', `Resuming session with ${data?.session?.advocate_name || 'Advocate'}`, 3000);
          //console.log(`_____________________________________START____________________________________________`);
          //console.trace();
          //console.log(`______________________________________END______________________________________________`);
          // show viewing session banner
          this.ui.showViewingSessionBanner(data?.session?.advocate_name || 'Advocate');
        }
        // Restore shared viewer with current document and page
        console.log('Restoring shared viewer with document:', data);
        if (data?.session?.document_url) {
          const pageNumber = data?.session?.current_page || 1;
          this.showShareViewer(data?.session?.document_url, pageNumber, data?.session?.advocate_name);
          
          // show the stop share button for judge
          this.showJudgeStopButton();
        }
      });
    }

    // Advocate callbacks (advocate role only)
    if (this.config.isAdvocate()) {
      // handle advocate reconnecting to active session
      this.wsClient.onSessionResumed((data) => {
        if (this.isSessionResumed) {
          console.log('Session already connected, ignoring duplicate session resumed event.');
          return;
        }
        console.log('Advocate reconnected to active session:', data);
        this.isSessionResumed = true;
        this.hideSummaryButton();
        if (this.ui) {
          // restore judge states from session data
          if (data.session && data.session.judges) {
            Object.entries(data.session.judges).forEach(([judgeId, judgeData]) => {
              this.ui.updateJudgeState(
                judgeId,
                judgeData.name,
                judgeData.state,
                judgeData.connected
              );
            });
          }
          
          // restore refer button to active state (state 3)
          this.ui.updateReferButtonState(3);
          this.ui.showNotification('info', 'Session restored', 3000);
        }
      });

      this.wsClient.onJudgeAccepted((data) => {
        console.log('Judge accepted referral:', data);
        this.hideSummaryButton();
        if (this.ui) {
          // track judge state
          this.ui.updateJudgeState(data.judge_id, data.judge_name, 'accepted', true);
          
          // Update refer button to active state (state 3)
          this.ui.updateReferButtonState(3);
          // Update judge list to show accepted status (handled by updateJudgeState)
          this.ui.showNotification('success', `${data.judge_name} has joined`, 4000);
        }
        // NOTE: Do NOT call showShareViewer for advocate - screen should only split on judge side
      });

      this.wsClient.onJudgeRejected((data) => {
        console.log('Judge rejected referral:', data);
        if (this.ui) {
          // track judge state
          this.ui.updateJudgeState(data.judge_id, data.judge_name, 'rejected', true);
          
          // only update button state if session is not active
          // if session active (at least one judge accepted), keep button in active state (state 3)
          // only show Rejected state (state 4) if all judges have rejected during request phase
          const hasActiveSession = this.wsClient.hasActiveSession();
          
          if (!hasActiveSession) {
            // check if all judges have rejected
            const allJudgesRejected = this.ui.areAllJudgesRejected();
            
            if (allJudgesRejected) {
              // all judges rejected - show rejected state
              this.ui.updateReferButtonState(4);
              this.showSummaryButton();
              
              // after 10 seconds cooldown, reset to default state (allow new request)
              setTimeout(() => {
                if (this.ui) {
                  this.ui.updateReferButtonState(1);
                }
              }, 10000);
            } else {
              // some judges still pending - keep pending state
              this.ui.updateReferButtonState(2);
            }
          }
          // if session is active, don't change button state (stays in state 3)
          
          const message = data.reason 
            ? `${data.judge_name} declined: ${data.reason}`
            : `${data.judge_name} declined the request`;
          this.ui.showNotification('warning', message, 6000);
        }
      });

      // handle ALL judge state changes (pending/accepted/rejected/reconnections)
      this.wsClient.onJudgeStateChanged((data) => {
        console.log('Generic judge state change:', data);
        if (this.ui) {
          // update judge state for ANY state change
          this.ui.updateJudgeState(
            data.judge_id,
            data.judge_name,
            data.state,
            data.connected !== false // default to true if not specified
          );
        }
      });

      this.wsClient.onReferralTimeout((data) => {
        console.log('Referral request timed out:', data);
        if (this.ui) {
          // All judges failed to respond within timeout period
          // Reset to default state (allow new request)
          this.ui.updateReferButtonState(1);
          this.ui.showNotification('warning', 'No judges responded to the request', 5000);
        }
      });

      this.wsClient.onJudgeDisconnected((data) => {
        console.log('Judge disconnected');
        if (this.ui) {
          // Reset refer button to default state
          this.ui.updateReferButtonState(1);
          this.ui.showNotification('warning', 'Judge disconnected', 5000);
        }
        this.hideShareViewer();
      });

      this.wsClient.onSessionEnded((data) => {
        console.log('Sharing session ended (advocate side):', data);
        this.shareViewerInitialized = false;
        this.isSessionResumed = false;
        if (this.ui) {
          // clear tracked judge states
          this.ui.clearJudgeStates();
          // Reset refer button to default state
          this.ui.updateReferButtonState(1);
          this.ui.hideActiveSessionBanner();
          this.ui.showNotification('info', data.message || 'Session ended', 5000);
        }
        this.showSummaryButton();
      });

      // Handle confirmation when judge receives the request
      this.wsClient.onRequestReceivedConfirmation((data) => {
        console.log('Judge confirmed receiving request:', data);
        if (this.ui && data.judge_id) {
          // Update judge state to mark requestReceived = true
          const judgeState = this.ui.judgeStates.get(data.judge_id);
          if (judgeState) {
            this.ui.updateJudgeState(
              data.judge_id,
              judgeState.name,
              judgeState.state,
              judgeState.connected,
              true  // requestReceived = true
            );
            console.log(`Judge ${data.judge_id} confirmed receiving request`);
          }
        }
      });
    }

    // Presence tracking callbacks (both roles)
    this.wsClient.onUserJoined((data) => {
      console.log('User joined case:', data);
      
      // Update judge list dropdown if advocate
      if (this.config.isAdvocate() && this.ui) {
        this.ui.updateAvailableJudgesList();
        
        // only show notification for new judges joining (not reconnecting judges)
        // note: advocate_reconnected event handles reconnection notifications
        // skip notification here if session is active to avoid duplicates
        if (data.role === 'judge' && !this.wsClient.hasActiveSession()) {
          this.ui.showNotification('info', `${data.user_name || 'Hon’ble Judge'} joined the case`, 4000);
          console.log('New judge available:', data.user_name);
        }
      }
    });

    this.wsClient.onUserLeft((data) => {
      console.log('User left case:', data);
      
      // Update judge list dropdown if advocate
      if (this.config.isAdvocate() && this.ui) {
        this.ui.updateAvailableJudgesList();
      }
    });

    // Roster management callbacks (both roles)
    this.wsClient.onJudgeAddedToCourtroom((data) => {
      console.log('Judge added to courtroom:', data);
      
      if (this.config.isAdvocate() && this.ui) {
        this.ui.updateAvailableJudgesList();
        this.ui.showNotification('info', `${data.judge_name} added to courtroom`, 3000);
      }
    });

    this.wsClient.onJudgeRemovedFromCourtroom((data) => {
      console.log('Judge removed from courtroom:', data);
      
      if (this.config.isAdvocate() && this.ui) {
        this.ui.updateAvailableJudgesList();
      }
    });

    // Generic notification callback
    this.wsClient.onNotification((data) => {
      if (this.ui) {
        this.ui.showNotification(data.type || 'info', data.message, data.duration);
      }
    });
  }

  /**
   * Set up page change synchronization for advocates
   */
  setupPageSynchronization() {
    if (!this.config.isAdvocate()) return;

    // Listen to page changes in main viewer
    if (window.PDFViewerApplication) {
      window.PDFViewerApplication.eventBus.on('pagechanging', (evt) => {
        if (this.wsClient && this.wsClient.hasActiveSession()) {
          // Debounce page updates to avoid flooding
          clearTimeout(this._pageUpdateTimeout);
          this._pageUpdateTimeout = setTimeout(() => {
            this.wsClient.updatePage(evt.pageNumber);
            console.log(`Syncing page ${evt.pageNumber} to judge`);
          }, 300);
        }
      });
    }
  }

  /**
   * Set up share viewer (simplified PDF viewer on right side)
   */
  setupShareViewer() {
    // Share viewer setup is primarily handled by the share-pdf.js template
    // This method can be used for additional initialization if needed
    
    const shareSectionContainer = document.getElementById('shareSectionContainer');
    if (shareSectionContainer) {
      // Hide by default
      shareSectionContainer.style.display = 'none';
      // setup judge stop button handler
      this.setupJudgeStopButton();
    }
  }
  
  /**
   * Setup the judge stop sharing button
   */
  setupJudgeStopButton() {
    const stopButton = document.getElementById('referStopBtnjude');
    if (!stopButton) {
      console.warn('Judge stop button not found');
      return;
    }
    
    // hide by default
    stopButton.style.display = 'none';
    
    // attach click handler
    stopButton.addEventListener('click', () => {
      console.log('Judge stopping share session');
      
      // confirm before leaving
      if (confirm('Are you sure you want to stop viewing this shared document?')) {
        this.judgeLeaveSession();
      }
    });
  }
  
  /**
   * Show the judge stop button
   */
  showJudgeStopButton() {
    const stopButton = document.getElementById('referStopBtnjude');
    if (stopButton) {
      stopButton.style.display = '';
    }
  }
  
  /**
   * Hide the judge stop button
   */
  hideJudgeStopButton() {
    const stopButton = document.getElementById('referStopBtnjude');
    if (stopButton) {
      stopButton.style.display = 'none';
    }
  }
  
  /**
   * Judge leaves the sharing session
   */
  judgeLeaveSession() {
    if (!this.config.isJudge()) {
      console.error('Only judges can leave session this way');
      return;
    }
    
    console.log('Judge leaving sharing session');
    
    // emit event to backend to update judge state
    if (this.wsClient) {
      this.wsClient.socket.emit('judge_leave_session', {
        courtroom_id: this.wsClient.config.courtroomId
      });
    }
    
    // close share viewer
    this.hideShareViewer();
    
    // hide viewing banner
    if (this.ui) {
      this.ui.hideViewingSessionBanner();
      this.ui.showNotification('info', 'You left the shared session', 3000);
    }
    
    // hide stop button
    this.hideJudgeStopButton();
    
    // clean up localStorage
    try {
      const storageKey = `referral_${this.wsClient.config.courtroomId}_${this.wsClient.config.userId}`;
      localStorage.removeItem(storageKey);
    } catch (e) {
      console.warn('Could not remove referral from localStorage:', e);
    }
  }

  /**
   * Initialize SharePDFViewerApplication (lazy initialization)
   * Creates a separate PDF viewer instance for the share viewer
   * 
   * NOTE: EventBus and PDFViewer classes are NOT exported from viewer.mjs
   * They are internal classes. We need to use the main PDFViewerApplication's
   * EventBus constructor or create a simpler implementation.
   */
  async initializeShareViewer() {
    try {
      // Check if we have the necessary PDF.js components
      if (typeof window.pdfjsLib === 'undefined') {
        throw new Error('PDF.js library not loaded');
      }

      if (!window.PDFViewerApplication) {
        throw new Error('Main PDFViewerApplication not initialized');
      }

      console.log('Creating SharePDFViewerApplication instance...');
      
      // Get EventBus constructor from the main viewer's instance
      const EventBusConstructor = window.PDFViewerApplication.eventBus.constructor;
      
      // Create event bus for share viewer
      const eventBus = new EventBusConstructor();
      
      // Get the container for share viewer
      const container = document.querySelector('#shareSectionContainer #viewerContainer');
      if (!container) {
        throw new Error('Share viewer container not found');
      }
      
      // Create a minimal share viewer instance
      // We'll manage document loading manually using pdfjsLib.getDocument
      window.SharePDFViewerApplication = {
        eventBus: eventBus,
        container: container,
        pdfDocument: null,
        currentPageNumber: 1,
        
        async open(url) {
          try {
            console.log('Loading document into share viewer:', url);
            
            // Close existing document if any
            if (this.pdfDocument) {
              await this.pdfDocument.destroy();
              this.pdfDocument = null;
            }
            
            // Load the new document
            const loadingTask = window.pdfjsLib.getDocument(url);
            const pdfDocument = await loadingTask.promise;
            this.pdfDocument = pdfDocument;
            
            // Render the first page
            await this.renderPage(1);
            
            console.log('Document loaded successfully in share viewer');
          } catch (error) {
            console.error('Error loading document in share viewer:', error);
            throw error;
          }
        },
        
        async renderPage(pageNumber) {
          if (!this.pdfDocument) {
            console.error('No document loaded');
            return;
          }
          
          try {
            this.currentPageNumber = pageNumber;
            
            // Clear existing content
            this.container.innerHTML = '';
            
            // Get the page
            const page = await this.pdfDocument.getPage(pageNumber);
            
            // Prepare canvas
            const canvas = document.createElement('canvas');
            const context = canvas.getContext('2d');
            
            // Calculate scale to fit container
            const viewport = page.getViewport({ scale: 1.0 });
            const containerWidth = this.container.clientWidth;
            const scale = containerWidth / viewport.width;
            const scaledViewport = page.getViewport({ scale });
            
            canvas.height = scaledViewport.height;
            canvas.width = scaledViewport.width;
            
            // Render page
            await page.render({
              canvasContext: context,
              viewport: scaledViewport
            }).promise;
            
            this.container.appendChild(canvas);
            console.log('append child redered');
            console.log(`Rendered page ${pageNumber} in share viewer`);
          } catch (error) {
            console.error('Error rendering page:', error);
            throw error;
          }
        }
      };

      console.log('SharePDFViewerApplication initialized successfully');
    } catch (error) {
      console.error('Failed to initialize SharePDFViewerApplication:', error);
      throw error;
    }
  }

  /**
   * Update shareAdvocate element with advocate name
   * @param {string} name - Advocate name to display
   */
  updateShareAdvocate(name) {
    const element = document.getElementById('shareAdvocate');
    if (element) {
      element.textContent = name || '';
      console.log('Updated shareAdvocate to:', name);
    }
  }

  /**
   * Update sharePageNumber element with current page
   * @param {number} page - Page number to display
   */
  updateSharePageNumber(page) {
    const element = document.getElementById('sharePageNumber');
    if (element) {
      element.value = page || 1;
      console.log('Updated sharePageNumber to:', page);
    }
  }

  /**
   * Clear both share elements when session ends
   */
  clearShareElements() {
    this.updateShareAdvocate('');
    this.updateSharePageNumber(1);
  }

  /**
   * Show share viewer with specified document and page
   * @param {string} documentIdOrUrl - Document UUID or document URL to load
   * @param {number} pageNumber - Initial page number
   * @param {string} advocateName - Optional advocate name to display
   */
  async showShareViewer(documentIdOrUrl, pageNumber, advocateName = null) {
    const shareSectionContainer = document.getElementById('shareSectionContainer');
    const fullViewerContainer = document.getElementById('fullViewerContainer');

    if (!shareSectionContainer || !fullViewerContainer) {
      console.error('Share viewer containers not found');
      return;
    }

    try {
      // Initialize SharePDFViewerApplication if not already initialized
      if (!window.SharePDFViewerApplication) {
        console.log('Initializing SharePDFViewerApplication...');
        await this.initializeShareViewer();
      }

      // Show split view
      fullViewerContainer.classList.add('width50');
      shareSectionContainer.classList.add('width50');
      shareSectionContainer.style.display = 'block';

      // Load document in share viewer
      await this.loadDocumentInShareViewer(documentIdOrUrl, pageNumber);

      // Update advocate name and page number in share viewer UI
      // Use passed advocateName or fallback to session info
      const displayName = advocateName || 
        (this.wsClient && this.wsClient.getSessionInfo ? this.wsClient.getSessionInfo().viewingWith : null) ||
        'Advocate';
      this.updateShareAdvocate(displayName);
      this.updateSharePageNumber(pageNumber || 1);

      console.log(`Share viewer shown with document ${documentIdOrUrl}, page ${pageNumber}`);
    } catch (error) {
      console.error('Failed to show share viewer:', error);
      if (this.ui) {
        this.ui.showNotification('error', 'Failed to load shared document', 5000);
      }
    }
  }

  /**
   * Hide share viewer and return to full width
   */
  hideShareViewer() {
    const shareSectionContainer = document.getElementById('shareSectionContainer');
    const fullViewerContainer = document.getElementById('fullViewerContainer');

    if (shareSectionContainer) {
      shareSectionContainer.style.display = 'none';
      shareSectionContainer.classList.remove('width50');
    }

    if (fullViewerContainer) {
      fullViewerContainer.classList.remove('width50');
    }

    // Clear and cleanup SharePDFViewerApplication instance
    if (window.SharePDFViewerApplication) {
      try {
        // Close the current document if loaded
        if (window.SharePDFViewerApplication.pdfDocument) {
          window.SharePDFViewerApplication.pdfDocument.destroy();
          window.SharePDFViewerApplication.pdfDocument = null;
        }
        
        // Clear the container
        if (window.SharePDFViewerApplication.container) {
          window.SharePDFViewerApplication.container.innerHTML = '';
        }
        
        console.log('SharePDFViewerApplication instance cleaned up');
      } catch (error) {
        console.error('Error cleaning up SharePDFViewerApplication:', error);
      }
    }

    // Clear share viewer instance reference
    if (this.shareViewerInstance) {
      this.shareViewerInstance = null;
    }

    // Clear share elements
    this.clearShareElements();

    console.log('Share viewer hidden and cleaned up');
  }

  /**
   * Load document into share viewer
   * @param {string} documentIdOrUrl - Document UUID or document URL
   * @param {number} pageNumber - Page to display
   */
  async loadDocumentInShareViewer(documentIdOrUrl, pageNumber) {
    let documentUrl;
    
    // Check if it's already a URL (starts with / or http)
    if (documentIdOrUrl.startsWith('/') || documentIdOrUrl.startsWith('http')) {
      documentUrl = documentIdOrUrl;
      console.log('Using provided document URL:', documentUrl);
    } else {
      // It's a UUID, look up the URL from config
      documentUrl = this.getDocumentUrl(documentIdOrUrl);
      
      if (!documentUrl) {
        throw new Error(`Document URL not found for UUID: ${documentIdOrUrl}`);
      }
      console.log('Resolved document URL from UUID:', documentUrl);
    }

    // Check if share viewer instance exists
    if (window.SharePDFViewerApplication) {
      try {
        // Load document
        await window.SharePDFViewerApplication.open(documentUrl);
        
        // Navigate to specific page if provided
        if (pageNumber && pageNumber > 0) {
          await window.SharePDFViewerApplication.renderPage(pageNumber);
        }

        this.shareViewerInstance = window.SharePDFViewerApplication;
      } catch (error) {
        console.error('Error loading document in share viewer:', error);
        throw error;
      }
    } else {
      console.error('SharePDFViewerApplication not initialized');
      throw new Error('Share viewer not available');
    }
  }

  /**
   * Sync share viewer to specific page
   * @param {number} pageNumber - Page number to navigate to
   */
  async syncToPage(pageNumber) {
    if(this.currentLoadedPage == pageNumber) {
      console.log(`------------------- >>>>>> Already on page ${pageNumber}, no need to sync`);
      return;
    }
    this.currentLoadedPage = pageNumber;
    if (window.SharePDFViewerApplication) {
      // if already rendered then don't re-render
      if (window.SharePDFViewerApplication.currentPageNumber === pageNumber && window.SharePDFViewerApplication.container.children.length > 0) {
        return;
      }
      try {
        await window.SharePDFViewerApplication.renderPage(pageNumber);
        this.updateSharePageNumber(pageNumber);
        console.log(`Synced share viewer to page ${pageNumber}`);
      } catch (error) {
        console.error('Error syncing page:', error);
      }
    }
  }

  /**
   * Get document URL from document ID
   * @param {string} documentId - Document UUID
   * @returns {string|null} Document URL
   */
  getDocumentUrl(documentId) {
    const documents = this.config.documents;
    
    if (!documents || typeof documents !== 'object') {
      return null;
    }

    // Search through all categories
    for (const category in documents) {
      const docs = documents[category];
      if (Array.isArray(docs)) {
        const doc = docs.find(d => d.fileuuid === documentId);
        if (doc && doc.url) {
          return doc.url;
        }
      }
    }

    return null;
  }

  /**
   * Notify judges that advocate has switched to a new PDF document
   * This is called from viewer-app.mjs when advocate clicks a new PDF file during active session
   * @param {string} documentUrl - URL of the new document
   * @param {number} pageNumber - Current page number (default: 1)
   */
  notifyDocumentChange(documentUrl, pageNumber = 1) {
    if (!this.config.isAdvocate()) {
      return; // Only advocates can notify document changes
    }

    if (!this.wsClient || !this.wsClient.hasActiveSession()) {
      return; // No active session, ignore
    }

    console.log('Notifying judges of document change:', documentUrl);
    this.wsClient.updateDocument(documentUrl, pageNumber);
  }

  /**
   * Hide the summary button when document sharing starts
   */
  hideSummaryButton() {
  const summaryBtn = document.getElementById('generateSummaryButton');
  if (summaryBtn) {
    summaryBtn.classList.add('d-none');
    summaryBtn.disabled = true;
    console.log('Summary button hidden');
  }
}

showSummaryButton() {
  const summaryBtn = document.getElementById('generateSummaryButton');
  if (summaryBtn) {
    summaryBtn.classList.remove('d-none');
    summaryBtn.disabled = false;
    console.log('Summary button shown');
  }
}


  /**
   * Clean up and disconnect
   */
  destroy() {
    console.log('Destroying document sharing integration');

    // Disconnect WebSocket
    if (this.wsClient) {
      this.wsClient.destroy();
      this.wsClient = null;
    }

    // Clean up UI
    if (this.ui) {
      this.ui.destroy();
      this.ui = null;
    }

    // Hide share viewer
    this.hideShareViewer();

    this.initialized = false;
  }

  /**
   * Check if document sharing is initialized and active
   * @returns {boolean}
   */
  isActive() {
    return this.initialized && this.wsClient && this.wsClient.isConnected();
  }

  /**
   * Get current session state
   * @returns {object|null}
   */
  getSessionState() {
    if (!this.wsClient) return null;
    return this.wsClient.state;
  }
}

// Create singleton instance
const documentSharingIntegration = new DocumentSharingIntegration();

// Expose to window for console debugging
if (typeof window !== 'undefined') {
    window.documentSharingIntegration = documentSharingIntegration;
    
    // Add convenient getter for config
    window.getDocViewerConfig = () => {
        if (!documentSharingIntegration.config) {
            console.warn('DocViewerConfig not initialized yet. Call DocumentSharingIntegration.initialize() first.');
            return null;
        }
        return documentSharingIntegration.config;
    };
    
    // Add convenient method to print config
    window.printDocViewerConfig = () => {
        const config = window.getDocViewerConfig();
        if (config) {
            config.printConfig();
        }
    };
}

// Export singleton as default
export default documentSharingIntegration;
